    !text.trim() ||
    text.length > 1800 ||
    text.trim().split(/\s+/u).length > 100 ||
    /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(text)
  )
    throw Error("OpenAI did not return a complete " + field + " within 100 words");
  return text.trim();
}

function embeddingRequest(summary, model) {
  return { input: summary, model, encoding_format: "float" };
}

