      request: embeddingRequest(summary, original.settings.embeddingModel),
    },
  },
];

function checkedVector(response, model) {
  const row = response?.data?.[0];
  if (
    response?.model !== model ||
    response?.data?.length !== 1 ||
    row?.index !== 0 ||
    !Array.isArray(row.embedding) ||
    !row.embedding.length ||
    row.embedding.some((value) => !Number.isFinite(value))
  ) {
    throw Error("OpenAI returned an invalid embedding for this email.");
  }
  return row.embedding;
}

const original = $("Prepare the embedding request").all(0, $runIndex)[0].json;
