      url:
        original.settings.qdrantOrigin +
        "/collections/" +
        encodeURIComponent(original.settings.collection) +
        "/points/query",
      request: { query: vector, limit: 4, with_payload: true, with_vector: false },
    },
  },
];

function checkedEvidence(points, payloadKey) {
  if (!Array.isArray(points) || points.length > 4)
    throw Error("Qdrant returned an invalid results page.");
  return points.map((point) => {
    const excerpt = point.payload?.[payloadKey];
    if (!Number.isFinite(point.score) || typeof excerpt !== "string" || !excerpt.trim()) {
      throw Error("Qdrant returned a result without the configured document text.");
    }
    return { id: String(point.id), excerpt: excerpt.trim().slice(0, 1800) };
  });
}

