function revisionDraft(response, inputs, parse, checkModelText) {
  const draft = checkModelText(response, "draft", parse);
  if (
    inputs.priorDraft &&
    draft.toLowerCase().replace(/\s+/g, " ") ===
      inputs.priorDraft.toLowerCase().replace(/\s+/g, " ")
  ) {
    throw Error("The model returned the same rejected reply. Draft the response manually.");
  }
  return draft;
}

function replyHtml(text, escape) {
  return "<p>" + escape(text).replace(/\n\n+/g, "</p><p>").replace(/\n/g, "<br>") + "</p>";
}

function escapeDraftHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

