  // Gmail Send and Wait decodes named entities once before composing MIME.
  const entities = {
    "&": "&#38;",
    "<": "&#60;",
    ">": "&#62;",
    '"': "&#34;",
    "'": "&#x27;",
    "\\": "&#92;",
  };
  return text.replace(/[&<>"'\\]/g, (character) => entities[character]);
