        reviewCode +
        "</strong></p>",
    },
  },
];

const { reviewCode, approvalMessage, request, ...draft } = $("Prepare review 3").all(
  0,
  $runIndex,
)[0].json;
const answer = $input.first().json.data;
const verified =
  typeof answer?.["Review code"] === "string" && answer["Review code"].trim() === reviewCode;
return [
  {
    json: {
      ...draft,
      approved: verified && answer.Decision === "Yes",
      revise: verified && answer.Decision === "No",
      priorDraft: draft.draft,
    },
  },
];
